// Watts, keyed by the firmware's own channel label.
const frame = context.panel.data.series[0];
if (!frame) {
  return {};
}
const read = (name) => {
  const field = frame.fields.find((f) => f.name === name);
  if (!field) {
    return [];
  }
  return field.values.toArray ? field.values.toArray() : Array.from(field.values);
};
const names = read('label');
const values = read('Value');
const watts = {};
names.forEach((name, i) => {
  watts[name] = Number(values[i]) || 0;
});
const at = (key) => watts[key] || 0;

// Residuals, not measurements: the firmware has no channel for board overhead
// or for whatever inside the package is not one of the four named rails, so
// both are differences and are clamped at zero rather than allowed to go
// negative when two channels are sampled a moment apart.
const rest = (whole, parts) => Math.max(0, at(whole) - parts);
const rails = at('gpu') + at('cpu_p') + at('cpu_e') + at('vcore');

const links = [
  { source: 'dc_input', target: 'sys_total', value: at('sys_total') },
  { source: 'dc_input', target: 'conversion', value: rest('dc_input', at('sys_total')) },
  { source: 'sys_total', target: 'soc_pkg', value: at('soc_pkg') },
  { source: 'sys_total', target: 'board', value: rest('sys_total', at('soc_pkg')) },
  { source: 'soc_pkg', target: 'gpu', value: at('gpu') },
  { source: 'soc_pkg', target: 'cpu_p', value: at('cpu_p') },
  { source: 'soc_pkg', target: 'cpu_e', value: at('cpu_e') },
  { source: 'soc_pkg', target: 'vcore', value: at('vcore') },
  { source: 'soc_pkg', target: 'uncore', value: rest('soc_pkg', rails) },
].filter((link) => link.value > 0.05);

const colour = {
  dc_input: '#5794f2',
  sys_total: '#73bf69',
  soc_pkg: '#f2cc0c',
  gpu: '#5794f2',
  cpu_p: '#b877d9',
  cpu_e: '#b877d9',
  vcore: '#ff9830',
  uncore: '#8e95a3',
  board: '#8e95a3',
  conversion: '#8e95a3',
};
// Only the nodes that still have a link. A node declared without one lands in
// the leftmost column at zero height and reads as a source of the flow: on an
// idle box that is `cpu_e` at 0.02 W and `conversion` at 0.
const linked = new Set();
links.forEach((link) => {
  linked.add(link.source);
  linked.add(link.target);
});
const nodes = [...linked].map((name) => ({
  name,
  itemStyle: { color: colour[name] || '#8e95a3' },
}));

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'item',
    valueFormatter: (value) => `${value.toFixed(1)} W`,
  },
  series: [
    {
      type: 'sankey',
      left: 8,
      right: 90,
      top: 12,
      bottom: 12,
      nodeGap: 14,
      nodeWidth: 14,
      emphasis: { focus: 'adjacency' },
      lineStyle: { color: 'gradient', opacity: 0.35 },
      label: {
        color: context.grafana.theme.colors.text.primary,
        formatter: (params) => `${params.name}  ${params.value.toFixed(0)} W`,
      },
      data: nodes,
      links,
    },
  ],
};
